import{_ as e,o as s,c as n,ae as t}from"./chunks/framework.DQC_QtFV.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"personal-bot","text":"自托管的个人助理","tagline":"跑在你自己的机器上，记忆存在你自己拥有的文件里，在你已经在用的聊天软件里回复你。","actions":[{"theme":"brand","text":"快速开始","link":"/guide/quick-start"},{"theme":"alt","text":"它是怎么工作的","link":"/guide/how-it-works"}]},"features":[{"title":"读","details":"收到的消息来自客户端自己数据库的一份私有解密副本，不接触客户端进程，就能拿到真实的消息 id、发送者、@、引用和图片。"},{"title":"写","details":"文字、图片、表情、@和引用回复都走客户端自己的发送函数，由一个带人类抖动的动作队列控制节奏。"},{"title":"记","details":"笔记由模型自己写下，是它唯一的长期记忆；每一轮、每次工具调用都记在可检索的日志里。"},{"title":"等","details":"wait、唤醒词、定时任务，以及可选的空闲轮：一段时间没有动静时，它有一轮属于自己的时间。"},{"title":"用工具","details":"网页搜索和阅读、沙箱里的命令行和文件、技能、MCP 服务端——每个函数都能在面板里单独开关。"},{"title":"面板","details":"实时画面与登录、会话与策略、人设、记忆、表情包、定时、模型、安全、工作区、高级设置和日志，一个页面一个主题。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793164923000}'),i={name:"index.md"};function l(p,a,o,r,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<div class="warning custom-block"><p class="custom-block-title">先读这一段</p><p>本项目驱动一个第三方桌面客户端，这不在该客户端服务条款允许的范围内，账号可能被限制或封禁。 请使用有小号历史记录的账号、家庭宽带，并保留默认的发送节奏。私人研究项目，按&quot;现状&quot;提供， 全部风险由使用者承担。运行前请先读 <a href="./guide/disclaimer.html">免责声明</a>。</p></div><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>四个容器：一个在虚拟显示里运行聊天客户端，另外三个分别是模型、你用来操作它的面板， 以及它的命令所在的沙箱。一个 stack 对应一个账号。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────── one stack = one account ──────────────────────────┐</span></span>
<span class="line"><span>│                                                                                  │</span></span>
<span class="line"><span>│  chat client (official, unmodified, headless)                                    │</span></span>
<span class="line"><span>│    │ writes              ▲ sends              ▲ clicks 登录                       │</span></span>
<span class="line"><span>│    ▼                     │                    │                                  │</span></span>
<span class="line"><span>│  private decrypted copy ──▶ driver API (HTTP + WebSocket)                        │</span></span>
<span class="line"><span>│                              │                        │                          │</span></span>
<span class="line"><span>│                              ▼                        ▼                          │</span></span>
<span class="line"><span>│                          console :8080            bot :8766                      │</span></span>
<span class="line"><span>│                          (the panel,              (the agent, notes,             │</span></span>
<span class="line"><span>│                           the live view)           the send review)              │</span></span>
<span class="line"><span>│                                                      │                           │</span></span>
<span class="line"><span>│                                                      ▼                           │</span></span>
<span class="line"><span>│                                                  sandbox :8791                   │</span></span>
<span class="line"><span>│                                                  (every command, as an           │</span></span>
<span class="line"><span>│                                                   unprivileged user)             │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h2><ul><li><a href="./guide/quick-start.html">快速开始</a>：环境要求、clone、<code>.env</code>、<code>docker compose up -d</code>。</li><li><a href="./guide/first-start.html">首次启动与扫码登录</a>：QQ 从哪来、密钥怎么读、二维码谁扫。</li><li><a href="./guide/env.html">环境变量</a>：<code>.env</code> 里每一个变量的含义。</li><li><a href="./guide/console/">控制台</a>：面板的每一个页面，一页一个主题。</li><li><a href="./guide/mcp.html">MCP 客户端</a>：让一个用 OAuth 认证的 MCP 服务端注册这个模型。</li></ul><h2 id="模型-pi-支持的都能用" tabindex="-1">模型：pi 支持的都能用 <a class="header-anchor" href="#模型-pi-支持的都能用" aria-label="Permalink to &quot;模型：pi 支持的都能用&quot;">​</a></h2><p>模型跑在 <a href="https://pi.dev" target="_blank" rel="noreferrer">pi</a> 上：pi 支持的每一家服务商、每一个模型都能用， 在<a href="./guide/console/models.html">控制台</a>的 模型 页登录服务商、或填一个 key 就行。 模型目录在机器人启动时拉取，之后每天自动刷新一次（<code>PI_OFFLINE=1</code> 时都不拉取），也可以随时手动刷新，新出的模型不用重启就会出现。</p><p>完整的项目说明在仓库的 <a href="https://github.com/4fuu/personal-bot" target="_blank" rel="noreferrer">README</a> 里； 上下文与记忆的机制细节在 <a href="https://github.com/4fuu/personal-bot/blob/main/docs/how-it-works.md" target="_blank" rel="noreferrer">docs/how-it-works.md</a>。</p>`,9)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
